package com.traphouse;

import java.time.Instant;
import java.util.List;

final class ClanEvent {
    final int id;
    final String title;
    final String metric;
    final Instant startsAt;
    final Instant endsAt;
    final List<LeaderboardEntry> scores;

    ClanEvent(int id, String title, String metric, Instant startsAt, Instant endsAt, List<LeaderboardEntry> scores) {
        this.id = id;
        this.title = title;
        this.metric = metric;
        this.startsAt = startsAt;
        this.endsAt = endsAt;
        this.scores = scores;
    }
}

package com.traphouse;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.util.Text;

/** Accessed on the client thread. Deduplicates alerts across refreshes and world hops. */
final class EventAlerts {
    private final Set<Integer> seen = new HashSet<>();
    private final Set<Integer> dayReminded = new HashSet<>();
    private final Set<Integer> hourReminded = new HashSet<>();
    private boolean initialized;

    void beginSession() { initialized = false; }

    List<String> poll(ClanEvent event, Instant now, boolean newEvents, boolean reminders) {
        List<String> messages = new ArrayList<>();
        boolean active = event != null && !now.isBefore(event.startsAt) && now.isBefore(event.endsAt);
        if (!initialized) {
            initialized = true;
            if (active) seen.add(event.id);
        }
        if (!active) return messages;
        String title = Text.removeTags(event.title) + " (" + EventSummary.target(event) + ")";
        if (seen.add(event.id) && newEvents) messages.add("New event started: " + title + ".");
        long seconds = java.time.Duration.between(now, event.endsAt).getSeconds();
        if (seconds <= 3600) {
            dayReminded.add(event.id);
            if (hourReminded.add(event.id) && reminders) messages.add(title + " ends in " + EventSummary.timing(event, now).replace(" left", "") + ".");
        } else if (seconds <= 86400 && dayReminded.add(event.id) && reminders) {
            messages.add(title + " ends in " + EventSummary.timing(event, now).replace(" left", "") + ".");
        }
        return messages;
    }
}

package com.traphouse;

import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.IntSupplier;
import javax.swing.SwingUtilities;

/** All state changes occur on Swing's event thread; HTTP work runs on the executor. */
final class EventLeaderboardController {
    private final WiseOldManClient client;
    private final ScheduledExecutorService executor;
    private final IntSupplier competitionId;
    private final boolean skillEvent;
    private TrapHousePanel panel;
    private Future<?> request;
    private volatile ClanEvent event;
    private volatile boolean checked;
    private boolean active = true;
    private long generation;
    private long lastRefresh;
    private String fetchedAt;
    private String playerName;

    EventLeaderboardController(WiseOldManClient client, ScheduledExecutorService executor, IntSupplier competitionId, boolean skillEvent) {
        this.client = client;
        this.executor = executor;
        this.competitionId = competitionId;
        this.skillEvent = skillEvent;
    }

    void setPanel(TrapHousePanel panel) {
        this.panel = panel;
        panel.updatePlayer(playerName);
        if (checked) panel.updateEvent(event, fetchedAt);
        if (request != null) panel.setLeaderboardLoading();
    }

    ClanEvent getEvent() { return event; }

    boolean isChecked() { return checked; }

    void updatePlayer(String name) {
        playerName = name;
        if (panel != null) panel.updatePlayer(name);
    }

    void refresh() {
        if (!active || request != null || panel == null) return;
        if (lastRefresh != 0 && System.nanoTime() - lastRefresh < TimeUnit.SECONDS.toNanos(30)) return;
        lastRefresh = System.nanoTime();
        long version = ++generation;
        panel.setLeaderboardLoading();
        int id = competitionId.getAsInt();
        request = executor.submit(() -> {
            try {
                ClanEvent fetched = client.fetchEvent(id, skillEvent);
                SwingUtilities.invokeLater(() -> received(version, fetched, null));
            } catch (Exception exception) {
                String error = exception instanceof java.io.IOException || exception instanceof IllegalArgumentException
                    ? exception.getMessage() : "Could not read Wise Old Man event scores.";
                SwingUtilities.invokeLater(() -> received(version, null, error));
            }
        });
    }

    private void received(long version, ClanEvent fetched, String error) {
        if (!active || version != generation) return;
        request = null;
        if (error != null) panel.setLeaderboardError(error);
        else {
            event = fetched;
            checked = true;
            fetchedAt = "Fetched " + LocalTime.now().format(DateTimeFormatter.ofPattern("HH:mm"));
            panel.updateEvent(event, fetchedAt);
        }
    }

    void reset() {
        ++generation;
        if (request != null) request.cancel(true);
        request = null;
        event = null;
        checked = false;
        lastRefresh = 0;
    }

    void stop() { active = false; reset(); panel = null; }
}

package com.traphouse;

import java.util.Locale;
import net.runelite.client.util.Text;

final class EventProgress {
    private EventProgress() { }

    static String describe(ClanEvent event, String player, boolean skill) {
        if (player == null || player.isEmpty()) return "Log in to see your event progress.";
        if (event == null) return "No event selected.";
        for (int index = 0; index < event.scores.size(); index++) {
            LeaderboardEntry entry = event.scores.get(index);
            if (!Text.standardize(entry.name.replace('_', ' ')).equals(Text.standardize(player.replace('_', ' ')))) continue;
            String unit = skill ? "XP" : "kills";
            String progress = String.format(Locale.US, "You: #%d / %,d %s gained", index + 1, entry.score, unit);
            if (index == 0) return progress + " / Leading!";
            long gap = event.scores.get(index - 1).score - entry.score;
            return progress + (gap == 0 ? " / Tied with the player above" : String.format(Locale.US, " / %,d %s behind #%d", gap, unit, index));
        }
        return "No recorded score for you in this event.";
    }
}

package com.traphouse;

import java.time.Duration;
import java.time.Instant;
import java.util.Locale;

final class EventSummary {
    private EventSummary() { }

    static String target(ClanEvent event) {
        String target = event.metric.replace('_', ' ');
        return target.isEmpty() ? target : target.substring(0, 1).toUpperCase(Locale.ROOT) + target.substring(1);
    }

    static String timing(ClanEvent event, Instant now) {
        if (!now.isBefore(event.endsAt)) return "Ended";
        boolean upcoming = now.isBefore(event.startsAt);
        long minutes = Math.max(1, (Duration.between(now, upcoming ? event.startsAt : event.endsAt).getSeconds() + 59) / 60);
        long days = minutes / 1440;
        long hours = minutes % 1440 / 60;
        String duration = days > 0 ? days + "d " + hours + "h"
            : hours > 0 ? hours + "h " + minutes % 60 + "m" : minutes + "m";
        return upcoming ? "Starts in " + duration : duration + " left";
    }
}

package com.traphouse;

/** A participant's kill or XP gains during a Wise Old Man competition. */
final class LeaderboardEntry {
