    }
}

package com.traphouse;

import com.google.inject.Provides;
import javax.inject.Inject;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(name="Trap House Clan Plugin", description="TRAP HOUSE boss and Skill of the Month Wise Old Man event leaderboards", tags={"clan","events","boss","skills","traphouse","leaderboard"})
public class TrapHouseClanPlugin extends Plugin {
    @Inject private ClientToolbar toolbar;
    @Inject private TrapHouseConfig config;
    @Inject private WiseOldManClient wiseOldMan;
    @Inject private ScheduledExecutorService executor;
    @Inject private Client client;
    @Inject private OverlayManager overlayManager;
    @Inject private TrapHouseEventOverlay eventOverlay;
    private NavigationButton navigationButton;
    private TrapHouseDashboard dashboard;
    private volatile EventLeaderboardController bossBoard;
    private volatile EventLeaderboardController skillBoard;
    private boolean loginSession;
    private boolean bossAnnounced;
    private boolean skillAnnounced;
    private ScheduledFuture<?> refreshTask;
    private boolean active;
    private String playerName;
    private EventAlerts bossAlerts;
    private EventAlerts skillAlerts;

    @Provides TrapHouseConfig provideConfig(ConfigManager manager) {
        return manager.getConfig(TrapHouseConfig.class);
    }

    @Override protected void startUp() {
        loginSession = false;
        playerName = null;
        bossAlerts = new EventAlerts();
        skillAlerts = new EventAlerts();
        overlayManager.add(eventOverlay);
        SwingUtilities.invokeLater(() -> {
            active = true;
            bossBoard = new EventLeaderboardController(wiseOldMan, executor, config::competitionId, false);
            skillBoard = new EventLeaderboardController(wiseOldMan, executor, config::skillCompetitionId, true);
            createPanel(0);
            refreshBoth();
        });
        refreshTask = executor.scheduleWithFixedDelay(() -> SwingUtilities.invokeLater(this::refreshBoth), 5, 5, TimeUnit.MINUTES);
    }

    private void createPanel(int selectedTab) {
        TrapHousePanel bossPanel = new TrapHousePanel(config, bossBoard::refresh, false);
        TrapHousePanel skillPanel = new TrapHousePanel(config, skillBoard::refresh, true);
        bossBoard.setPanel(bossPanel);
        skillBoard.setPanel(skillPanel);
        dashboard = new TrapHouseDashboard(bossPanel, skillPanel, selectedTab);
        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
        navigationButton = NavigationButton.builder().tooltip("TRAP HOUSE").icon(icon).priority(6).panel(dashboard).build();
        toolbar.addNavigation(navigationButton);
    }

    private void refreshBoth() {
        if (!active) return;
        bossBoard.refresh();
        skillBoard.refresh();
    }

    @Override protected void shutDown() {
        overlayManager.remove(eventOverlay);
        loginSession = false;
        if (refreshTask != null) refreshTask.cancel(false);
        refreshTask = null;
        SwingUtilities.invokeLater(() -> {
            active = false;
            bossBoard.stop();
            skillBoard.stop();
            if (navigationButton != null) toolbar.removeNavigation(navigationButton);
            navigationButton = null;
            dashboard = null;
        });
    }

    @Subscribe public void onConfigChanged(ConfigChanged event) {
        if (!"traphouse".equals(event.getGroup())) return;
        if (!"competitionId".equals(event.getKey()) && !"skillCompetitionId".equals(event.getKey())) return;
        SwingUtilities.invokeLater(() -> {
            if (!active) return;
            if ("competitionId".equals(event.getKey())) bossBoard.reset();
            if ("skillCompetitionId".equals(event.getKey())) skillBoard.reset();
            int tab = dashboard.selectedTab();
            toolbar.removeNavigation(navigationButton);
            createPanel(tab);
            refreshBoth();
        });
    }

    ClanEvent getEvent(boolean skill) {
        EventLeaderboardController board = skill ? skillBoard : bossBoard;
        return board == null ? null : board.getEvent();
    }

    boolean isEventChecked(boolean skill) {
        EventLeaderboardController board = skill ? skillBoard : bossBoard;
        return board != null && board.isChecked();
    }

    @Subscribe public void onGameStateChanged(GameStateChanged event) {
        // Hopping and loading stay in the same session; returning to login resets it.
        if (event.getGameState() == GameState.LOGIN_SCREEN) {
            loginSession = false;
            updatePlayer(null);
        }
    }

    @Subscribe public void onGameTick(GameTick tick) {
        if (client.getGameState() != GameState.LOGGED_IN) return;
        updatePlayer(client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName());
        if (!loginSession) {
            loginSession = true;
            bossAnnounced = !config.announceOnLogin();
            skillAnnounced = !config.announceOnLogin();
            bossAlerts.beginSession();
            skillAlerts.beginSession();
            SwingUtilities.invokeLater(this::refreshBoth);
        }
        if (config.announceOnLogin() && !bossAnnounced && isEventChecked(false)) {
            announceEvent(false);
            bossAnnounced = true;
        }
        if (config.announceOnLogin() && !skillAnnounced && isEventChecked(true)) {
            announceEvent(true);
            skillAnnounced = true;
        }
        pollAlerts(false, bossAlerts);
        pollAlerts(true, skillAlerts);
    }

    private void updatePlayer(String name) {
        if (java.util.Objects.equals(playerName, name)) return;
        playerName = name;
        SwingUtilities.invokeLater(() -> {
            if (!active) return;
            bossBoard.updatePlayer(name);
            skillBoard.updatePlayer(name);
        });
    }

    private void pollAlerts(boolean skill, EventAlerts alerts) {
        if (!isEventChecked(skill)) return;
        boolean automatic = (skill ? config.skillCompetitionId() : config.competitionId()) == 0;
        for (String message : alerts.poll(getEvent(skill), java.time.Instant.now(),
            config.newEventAlerts() && automatic, config.eventEndingReminders())) {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[Trap House] " + (skill ? "Skill: " : "Boss: ") + message, null);
        }
    }

    private void announceEvent(boolean skill) {
        ClanEvent event = getEvent(skill);
        String kind = skill ? "Skill event" : "Boss event";
        String message = event == null ? "[Trap House] " + kind + ": no active event."
            : "[Trap House] " + kind + ": " + Text.removeTags(event.title) + " — "
                + EventSummary.target(event) + " (" + EventSummary.timing(event, java.time.Instant.now()) + ").";
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }
}

package com.traphouse;

import net.runelite.client.config.*;

@ConfigGroup("traphouse")
public interface TrapHouseConfig extends Config {
    @ConfigItem(keyName="competitionId", name="Wise Old Man competition ID", description="0 automatically selects the current Trap House boss competition. Enter a competition ID to view a specific event, including ended events.", position=1)
    @Range(min=0)
    default int competitionId() { return 0; }

    @ConfigItem(keyName="skillCompetitionId", name="Skill of the Month competition ID", description="0 detects the current Trap House single-skill competition. Enter an ID to select a specific skill event.", position=2)
    @Range(min=0)
    default int skillCompetitionId() { return 0; }

    @ConfigItem(keyName="announceOnLogin", name="Announce events on login", description="Show the boss and skill events in your game chat once per login.", position=3)
    default boolean announceOnLogin() { return true; }

    @ConfigItem(keyName="showEventOverlay", name="Show event overlay", description="Display the boss and skill event targets and time remaining on screen.", position=4)
    default boolean showEventOverlay() { return true; }

    @ConfigItem(keyName="showBossOverlay", name="Boss event in overlay", description="Include the boss event when the event overlay is enabled.", position=5)
    default boolean showBossOverlay() { return true; }

    @ConfigItem(keyName="showSkillOverlay", name="Skill event in overlay", description="Include the skill event when the event overlay is enabled.", position=6)
    default boolean showSkillOverlay() { return true; }

    @ConfigItem(keyName="showOverlayLeaders", name="Top three in overlay", description="Include the top three participants for each visible event.", position=7)
    default boolean showOverlayLeaders() { return false; }

    @ConfigItem(keyName="eventEndingReminders", name="Event ending reminders", description="Privately remind you when an active event has a day or an hour remaining.", position=8)
    default boolean eventEndingReminders() { return true; }

    @ConfigItem(keyName="newEventAlerts", name="New event alerts", description="Privately announce new active events detected while you are playing.", position=9)
    default boolean newEventAlerts() { return true; }

}

package com.traphouse;

import java.awt.BorderLayout;
import java.awt.Font;
import javax.swing.JTabbedPane;
import net.runelite.client.ui.PluginPanel;

final class TrapHouseDashboard extends PluginPanel {
    private final JTabbedPane tabs = new JTabbedPane();

    TrapHouseDashboard(TrapHousePanel bossPanel, TrapHousePanel skillPanel, int selectedTab) {
        setLayout(new BorderLayout());
        tabs.setFont(new Font("SansSerif", Font.BOLD, 11));
        tabs.addTab("Boss event", bossPanel);
        tabs.addTab("Skill event", skillPanel);
        tabs.setToolTipTextAt(0, "Boss of the Week: competition kill gains");
        tabs.setToolTipTextAt(1, "Skill of the Month: competition XP gains");
        tabs.setSelectedIndex(selectedTab);
        add(tabs, BorderLayout.CENTER);
    }

    int selectedTab() { return tabs.getSelectedIndex(); }
}

package com.traphouse;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.time.Instant;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class TrapHouseEventOverlay extends OverlayPanel {
    private final Client client;
    private final TrapHouseConfig config;
    private final TrapHouseClanPlugin plugin;
    private final PanelComponent bossSection = createSection();
    private final PanelComponent skillSection = createSection();

    @Inject
    TrapHouseEventOverlay(Client client, TrapHouseConfig config, TrapHouseClanPlugin plugin) {
        super(plugin);
        this.client = client;
        this.config = config;
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(230, 0));
        panelComponent.setBackgroundColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
        panelComponent.setGap(new Point(0, 12));
    }

    @Override public Dimension render(Graphics2D graphics) {
        if (!config.showEventOverlay() || (!config.showBossOverlay() && !config.showSkillOverlay())
            || client.getGameState() != GameState.LOGGED_IN) return null;
        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder().text("TRAP HOUSE Events").color(new Color(237, 190, 102)).build());
        if (config.showBossOverlay()) addEvent(false);
        if (config.showSkillOverlay()) addEvent(true);
        return super.render(graphics);
    }

    private static PanelComponent createSection() {
        PanelComponent section = new PanelComponent();
        section.setBackgroundColor(null);
        section.setBorder(new Rectangle());
        section.setGap(new Point(0, 3));
        return section;
    }

    private void addEvent(boolean skill) {
        PanelComponent section = skill ? skillSection : bossSection;
        section.getChildren().clear();
        ClanEvent event = plugin.getEvent(skill);
        String target = event == null ? (plugin.isEventChecked(skill) ? "No active event" : "Loading...") : EventSummary.target(event);
        section.getChildren().add(LineComponent.builder().left(skill ? "SKILL EVENT" : "BOSS EVENT")
            .leftColor(new Color(237, 190, 102)).right(target).build());
        if (event != null) {
            section.getChildren().add(LineComponent.builder().left(EventSummary.timing(event, Instant.now())).leftColor(Color.LIGHT_GRAY).build());
            if (config.showOverlayLeaders()) {
                for (int index = 0; index < Math.min(3, event.scores.size()); index++) {
                    LeaderboardEntry entry = event.scores.get(index);
                    section.getChildren().add(LineComponent.builder().left((index + 1) + ". " + net.runelite.client.util.Text.removeTags(entry.name))
                        .right(String.format(Locale.US, "%,d %s", entry.score, skill ? "XP" : "kills")).build());
                }
            }
        }
        panelComponent.getChildren().add(section);
    }
}

package com.traphouse;

import java.awt.*;
import java.util.Locale;
import java.util.List;
import java.util.Collections;
