package com.traphouse;

import com.google.gson.Gson;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.laf.RuneLiteLAF;
import okhttp3.OkHttpClient;

/** Side-by-side rendering of both tabs using the real components and current WOM events. */
public class TrapHouseBothTabsPreview {
    public static void main(String[] args) throws Exception {
        OkHttpClient http = new OkHttpClient();
        ClanEvent boss;
        ClanEvent skill;
        try {
            WiseOldManClient client = new WiseOldManClient(http, new Gson());
            boss = client.fetchEvent(0, false);
            skill = client.fetchEvent(0, true);
        } finally {
            http.dispatcher().executorService().shutdown();
            http.connectionPool().evictAll();
        }
        SwingUtilities.invokeAndWait(() -> {
            RuneLiteLAF.setup();
            TrapHouseDashboard left = dashboard(boss, skill, 0);
            TrapHouseDashboard right = dashboard(boss, skill, 1);
            int height = Math.max(left.getPreferredSize().height, right.getPreferredSize().height);
            left.setSize(225, height);
            right.setSize(225, height);
            layout(left);
            layout(right);
            BufferedImage image = new BufferedImage(948, (height + 24) * 2, BufferedImage.TYPE_INT_RGB);
            Graphics2D graphics = image.createGraphics();
            graphics.setColor(new Color(15, 17, 22));
            graphics.fillRect(0, 0, image.getWidth(), image.getHeight());
            graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            graphics.scale(2, 2);
            graphics.translate(6, 12);
            left.printAll(graphics);
            graphics.translate(237, 0);
            right.printAll(graphics);
            graphics.dispose();
            try {
                File output = new File("build/trap-house-both-tabs.png");
                output.getParentFile().mkdirs();
                ImageIO.write(image, "png", output);
                System.out.println("Both tabs saved to " + output.getAbsolutePath());
            } catch (Exception exception) { throw new RuntimeException(exception); }
        });
    }

    private static TrapHouseDashboard dashboard(ClanEvent boss, ClanEvent skill, int selectedTab) {
        TrapHousePanel bossPanel = new TrapHousePanel(new TrapHouseConfig() {}, () -> {}, false);
        TrapHousePanel skillPanel = new TrapHousePanel(new TrapHouseConfig() {}, () -> {}, true);
        bossPanel.updateEvent(boss, "Fetched live event data");
        skillPanel.updateEvent(skill, "Fetched live event data");
        return new TrapHouseDashboard(bossPanel, skillPanel, selectedTab);
    }

    private static void layout(Container container) {
        container.doLayout();
        for (Component component : container.getComponents()) {
            if (component instanceof Container) layout((Container) component);
        }
    }
}

package com.traphouse;

import java.awt.Container;
import java.awt.Component;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.nio.file.Files;
import java.nio.charset.StandardCharsets;
import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import javax.imageio.ImageIO;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.laf.RuneLiteLAF;

/** Renders the actual sidebar without starting a game client. */
public class TrapHousePanelPreview {
    public static void main(String[] args) throws Exception {
        boolean hasData = args.length > 0;
        boolean skillEvent = hasData && "--skill-live".equals(args[0]);
        ClanEvent event = null;
        if (hasData) {
            if ("--live".equals(args[0]) || skillEvent) {
                int competitionId = args.length > 1 ? Integer.parseInt(args[1]) : 0;
                OkHttpClient http = new OkHttpClient();
                try {
                    event = new WiseOldManClient(http, new Gson()).fetchEvent(competitionId, skillEvent);
                    System.out.println(event == null ? "No active " + (skillEvent ? "skill" : "boss") + " event in group 2504"
                        : "Event " + event.id + ": " + event.scores.size() + " participants loaded");
                } finally {
                    http.dispatcher().executorService().shutdown();
                    http.connectionPool().evictAll();
                }
            } else {
                String json = new String(Files.readAllBytes(new File(args[0]).toPath()), StandardCharsets.UTF_8);
                event = WiseOldManClient.parseEvent(json, new Gson());
            }
        }
        ClanEvent previewEvent = event;
        SwingUtilities.invokeAndWait(() -> {
            RuneLiteLAF.setup();
            TrapHousePanel bossPanel = new TrapHousePanel(new TrapHouseConfig() {}, () -> {}, false);
            TrapHousePanel skillPanel = new TrapHousePanel(new TrapHouseConfig() {}, () -> {}, true);
            if (hasData) (skillEvent ? skillPanel : bossPanel).updateEvent(previewEvent, "Fetched preview data");
            TrapHouseDashboard panel = new TrapHouseDashboard(bossPanel, skillPanel, skillEvent ? 1 : 0);
            panel.setSize(225, panel.getPreferredSize().height);
            layout(panel);
            BufferedImage image = new BufferedImage(450, panel.getHeight() * 2, BufferedImage.TYPE_INT_RGB);
            Graphics2D graphics = image.createGraphics();
            graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            graphics.scale(2, 2);
            panel.printAll(graphics);
            graphics.dispose();
            try {
                File output = new File("build/trap-house-preview.png");
                output.getParentFile().mkdirs();
                ImageIO.write(image, "png", output);
                System.out.println("Preview saved to " + output.getAbsolutePath());
            } catch (Exception exception) { throw new RuntimeException(exception); }
        });
    }

    private static void layout(Container container) {
        container.doLayout();
        for (Component component : container.getComponents()) {
            if (component instanceof Container) layout((Container) component);
        }
    }
}

package com.traphouse;

import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.List;
import java.util.Arrays;
import java.util.Collections;
import java.time.Instant;
import javax.swing.JTabbedPane;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.util.ImageUtil;
import org.junit.Test;
import static org.junit.Assert.*;

public class TrapHousePanelTest {
    @Test
    public void sidebarIconIsPackagedAtPluginResourcePath() {
        assertNotNull(ImageUtil.loadImageResource(TrapHouseClanPlugin.class, "icon.png"));
        assertNotNull(ImageUtil.loadImageResource(TrapHousePanel.class, "logo.png"));
    }

    @Test
    public void leaderboardDisplaysScoresAndCommunityLinkButtons() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            TrapHousePanel panel = new TrapHousePanel(new TrapHouseConfig() {}, () -> {});
            panel.updateLeaderboard(Arrays.asList(new LeaderboardEntry("Clan member", 12),
                new LeaderboardEntry("Another member", 7)), "Fetched 12:00");
            assertTrue(hasLabel(panel, "BOSS KILL LEADERBOARD"));
            assertTrue(hasLabel(panel, "Clan member"));
            assertTrue(hasLabel(panel, "7"));
            assertTrue(hasLabel(panel, "12"));
            int links = 0;
            for (Component component : descendants(panel)) {
                if (component instanceof JButton && ("Open Discord".equals(((JButton) component).getText())
                    || "Open Clan Website".equals(((JButton) component).getText()))) {
                    assertTrue(component.isEnabled());
                    links++;
                }
            }
            assertEquals(2, links);
        });
    }

    @Test
    public void emptyLeaderboardDoesNotInventKills() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            TrapHousePanel panel = new TrapHousePanel(new TrapHouseConfig() {}, () -> {});
            panel.updateLeaderboard(Collections.emptyList(), "Fetched 12:00");
            assertTrue(hasLabel(panel, "<html><div style='width:126px'>No scored participants yet</div></html>"));
            assertTrue(hasLabel(panel, "WISE OLD MAN / GROUP 2504"));
            assertFalse(hasLabel(panel, "NEARBY BOSS DEATHS"));
        });
    }

    @Test public void failedRefreshPreservesPreviouslyFetchedScores() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            TrapHousePanel panel = new TrapHousePanel(new TrapHouseConfig() {}, () -> {});
            panel.updateLeaderboard(Collections.singletonList(new LeaderboardEntry("Member", 1836)), "Fetched 12:00");
            panel.setLeaderboardLoading();
            panel.setLeaderboardError("Wise Old Man unavailable.");
            assertTrue(hasLabel(panel, "Member"));
            assertTrue(hasLabel(panel, "1,836"));
        });
    }

    @Test public void noCurrentEventClearsPreviousScores() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            TrapHousePanel panel = new TrapHousePanel(new TrapHouseConfig() {}, () -> {});
            panel.updateLeaderboard(Collections.singletonList(new LeaderboardEntry("Member", 100)), "Fetched 12:00");
            panel.updateEvent(null, "Fetched 12:05");
            assertFalse(hasLabel(panel, "Member"));
            assertTrue(hasLabel(panel, "No active boss event"));
            assertTrue(hasLabel(panel, "KILLS GAINED DURING EVENT"));
        });
    }

    @Test public void eventLinkAndPersonalProgressFollowSelectedCompetition() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            for (boolean skill : new boolean[] {false, true}) {
                TrapHousePanel panel = new TrapHousePanel(new TrapHouseConfig() {}, () -> {}, skill);
                JButton link = null;
                for (Component component : descendants(panel)) {
                    if (component instanceof JButton && "Open on Wise Old Man".equals(((JButton) component).getText())) link = (JButton) component;
                }
                assertNotNull(link);
                assertFalse(link.isEnabled());
                panel.updatePlayer("Member");
                panel.updateEvent(new ClanEvent(123, "Test", skill ? "fishing" : "vorkath", Instant.now().minusSeconds(60),
                    Instant.now().plusSeconds(60), Collections.singletonList(new LeaderboardEntry("Member", 20))), "Fetched now");
                assertTrue(link.isEnabled());
                assertEquals("https://wiseoldman.net/competitions/123", link.getToolTipText());
                assertTrue(hasLabel(panel, "<html><div style='width:126px'>You: #1 / 20 " + (skill ? "XP" : "kills") + " gained / Leading!</div></html>"));
                panel.updateEvent(null, "Fetched now");
                assertFalse(link.isEnabled());
                assertTrue(hasLabel(panel, "<html><div style='width:126px'>No event selected.</div></html>"));
            }
        });
    }

    @Test public void skillTabShowsXpGainsAndFixedPrizes() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            TrapHousePanel skill = new TrapHousePanel(new TrapHouseConfig() {}, () -> {}, true);
            ClanEvent event = new ClanEvent(1, "Skill of the Month: Sailing", "sailing", Instant.now().minusSeconds(60),
                Instant.now().plusSeconds(60), Collections.singletonList(new LeaderboardEntry("Member", 1234567)));
            skill.updateEvent(event, "Fetched 12:00");
            assertTrue(hasLabel(skill, "SKILL OF THE MONTH"));
            assertTrue(hasLabel(skill, "SKILL XP LEADERBOARD"));
            assertTrue(hasLabel(skill, "1.2M"));
            assertTrue(hasLabel(skill, "XP"));
            assertTrue(hasLabel(skill, "10,000,000 GP"));
            assertTrue(hasLabel(skill, "5,000,000 GP"));
            assertTrue(hasLabel(skill, "2,500,000 GP"));
            assertFalse(hasLabel(skill, "KILLS"));
            TrapHouseDashboard dashboard = new TrapHouseDashboard(new TrapHousePanel(new TrapHouseConfig() {}, () -> {}), skill, 1);
            assertEquals(1, dashboard.selectedTab());
            for (Component component : descendants(dashboard)) {
                if (component instanceof JTabbedPane) assertEquals(2, ((JTabbedPane) component).getTabCount());
            }
        });
    }

    private static boolean hasLabel(TrapHousePanel panel, String text) {
        for (Component component : descendants(panel)) {
            if (component instanceof JLabel && text.equals(((JLabel) component).getText())) return true;
        }
        return false;
    }

    private static List<Component> descendants(Container container) {
        List<Component> components = new ArrayList<>();
        for (Component component : container.getComponents()) {
            components.add(component);
            if (component instanceof Container) components.addAll(descendants((Container) component));
        }
        return components;
    }
}

